// 惠山 dev 登录 + 资金拨付详情探测（带 cookie）。
// step1: 取验证码存图+uuid；step2: 读答案登录；step3: 拉详情
import { writeFileSync, readFileSync } from 'node:fs'

const BASE = 'http://unlimited.g.h5.admin.web.v2.product.huishan.wuxi.dev.zhi.com/api/v2.0'
const TMP = 'C:/Users/Administrator/AppData/Local/Temp/'
const CAP = TMP + 'hs_cap.jpg'
const UUIDF = TMP + 'hs_uuid.txt'
const COOKIEF = TMP + 'hs_cookie.txt'
const TOKENF = TMP + 'hs_token.txt'
const ANSF = TMP + 'hs_answer.txt'

const mode = process.argv[2] || 'step1'
const BASE_ORIGIN = 'http://unlimited.g.h5.admin.web.v2.product.huishan.wuxi.dev.zhi.com'

if (mode === 'step1') {
  const r = await fetch(BASE + '/code')
  const cap = await r.json()
  const cookies = r.headers.getSetCookie ? r.headers.getSetCookie() : []
  const buf = Buffer.from(String(cap.data).replace(/^data:image\/\w+;base64,/, ''), 'base64')
  writeFileSync(CAP, buf)
  writeFileSync(UUIDF, cap.uuid)
  writeFileSync(COOKIEF, cookies.join('\n'))
  console.log('captcha ->', CAP)
  console.log('uuid =', cap.uuid)
  console.log('cookies =', cookies.length)
} else if (mode === 'step2') {
  const answer = readFileSync(ANSF, 'utf8').trim()
  const uuid = readFileSync(UUIDF, 'utf8').trim()
  let cookieHdr = ''
  try {
    cookieHdr = readFileSync(COOKIEF, 'utf8')
      .split('\n')
      .filter(Boolean)
      .map((c) => c.split(';')[0])
      .join('; ')
  } catch (e) {}
  const r = await fetch(BASE + '/security/auth/login', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(cookieHdr ? { Cookie: cookieHdr } : {})
    },
    body: JSON.stringify({ username: 'zsbase', password: 'ZS001Aa!', code: answer, uuid })
  })
  const body = await r.text()
  console.log('LOGIN', r.status, body.slice(0, 400))
  try {
    const p = JSON.parse(body)
    const t = p.token || (p.data && (p.data.accessToken || p.data.token))
    if (t) {
      writeFileSync(TOKENF, String(t))
      console.log('TOKEN saved')
    }
    const setc = r.headers.getSetCookie ? r.headers.getSetCookie() : []
    if (setc.length) writeFileSync(COOKIEF, setc.join('\n'))
  } catch (e) {}
} else {
  const token = readFileSync(TOKENF, 'utf8').trim()
  const listRes = await fetch(BASE + '/benefit/pubAllotNotice/page?pageNum=1&pageSize=10', {
    headers: { Authorization: token.startsWith('Bearer') ? token : 'Bearer ' + token }
  })
  const lt = await listRes.text()
  console.log('LIST', listRes.status, lt.slice(0, 900))
}

