import { chromium } from 'playwright'
import { writeFileSync, readFileSync, existsSync } from 'node:fs'

const SITE = process.env.HS_SITE || 'http://127.0.0.1:8098'
const TMP = 'C:/Users/Administrator/AppData/Local/Temp/'
const CAPJPG = TMP + 'pw_cap.jpg'
const ANSF = TMP + 'pw_answer.txt'
const STATE = TMP + 'pw_state.json'

const mode = process.argv[2] || 'login'

const browser = await chromium.launch({ headless: true })
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } })
const page = await ctx.newPage()

if (mode === 'login') {
  let codeBody = null
  page.on('response', async (r) => {
    if (r.url().includes('/code')) {
      try { codeBody = await r.json() } catch (e) {}
    }
  })
  await page.goto(SITE + '/login', { waitUntil: 'networkidle', timeout: 60000 })
  // 触发一次验证码请求（页面加载时通常已请求）
  if (!codeBody) {
    await page.reload({ waitUntil: 'networkidle', timeout: 60000 })
  }
  if (!codeBody || !codeBody.data) {
    console.log('NO_CAPTCHA_RESPONSE')
    await browser.close()
    process.exit(1)
  }
  const b64 = String(codeBody.data).replace(/^data:image\/\w+;base64,/, '')
  writeFileSync(CAPJPG, Buffer.from(b64, 'base64'))
  console.log('captcha saved, uuid =', codeBody.uuid)
  await page.screenshot({ path: TMP + 'pw_login.png' })
  await ctx.storageState({ path: STATE })
  console.log('ready for answer; run step2 with answer')
  await browser.close()
} else if (mode === 'submit') {
  const answer = readFileSync(ANSF, 'utf8').trim()
  let codeBody = null
  page.on('response', async (r) => {
    if (r.url().includes('/code')) { try { codeBody = await r.json() } catch (e) {} }
  })
  await page.goto(SITE + '/login', { waitUntil: 'networkidle', timeout: 60000 })
  console.log('loaded, uuid =', codeBody && codeBody.uuid)
  await page.fill('input[placeholder="请输入用户名"]', 'zsbase')
  await page.fill('input[placeholder="请输入用户密码"]', 'ZS001Aa!')
  await page.fill('input[placeholder="请输入验证码"]', answer)
  const resp = page.waitForResponse((r) => r.url().includes('/security/auth/login'), { timeout: 30000 }).catch(() => null)
  await page.locator('.login-button').evaluate((el) => el.click())
  const lr = await resp
  if (lr) {
    console.log('LOGIN API', lr.status(), (await lr.text()).slice(0, 300))
  } else {
    console.log('no login response captured')
  }
  await page.waitForTimeout(3000)
  console.log('URL after login:', page.url())
  await page.screenshot({ path: TMP + 'pw_after_login.png', fullPage: false })
  await ctx.storageState({ path: STATE })
  await browser.close()
}

